(4851828, 704072, 73056, '<td valign="top">I love the simplicity behind this. Excellent crop, shadow and composition.</td>', 'I love the simplicity behind this. Excellent crop, shadow and composition.', '2008-07-30 19:16:04.000000', NULL, 1),
(4851855, 704064, 93696, '<td valign="top">I really like the image and the objects ;-) I might be wrong, but did you add lens vignetting as an effect after the image was taken? If so, I am afraid it is against the basic editing rules...</td>', 'I really like the image and the objects ;-) I might be wrong, but did you add lens vignetting as an effect after the image was taken? If so, I am afraid it is against the basic editing rules...', '2008-07-30 19:28:50.000000', NULL, 1),
(4851858, 702574, 93696, '<td valign="top">Nice, simple and clean. Well done! ;-)</td>', 'Nice, simple and clean. Well done! ;-)', '2008-07-30 19:29:28.000000', NULL, 1),
(4851865, 702460, 93696, '<td valign="top">It seems very unclear to me what the subject of this image is - and therefore it doesnt "express" anything either. Perhaps you could have cropped the image to draw the viewers attention to a specific item, or compose the image in a way that the viewer know what to focus on.</td>', 'It seems very unclear to me what the subject of this image is - and therefore it doesnt "express" anything either. Perhaps you could have cropped the image to draw the viewers attention to a specific item, or compose the image in a way that the viewer know what to focus on.', '2008-07-30 19:33:01.000000', NULL, 1),
(4851866, 703848, 73056, '<td valign="top">Looks rich and wonderful in black and white. Nice shot and processing!</td>', 'Looks rich and wonderful in black and white. Nice shot and processing!', '2008-07-30 19:33:28.000000', NULL, 1),
(4851870, 702417, 73056, '<td valign="top">Cool shot!</td>', 'Cool shot!', '2008-07-30 19:34:49.000000', NULL, 1),
(4851876, 703998, 93696, '<td valign="top">To me, it would have been more interesting if the lighting on the bed would be much more darker - as to create a contrast between day and night, white and black.</td>', 'To me, it would have been more interesting if the lighting on the bed would be much more darker - as to create a contrast between day and night, white and black.', '2008-07-30 19:36:17.000000', NULL, 1),
(4851879, 704024, 93696, '<td valign="top">Are the colors desaturated on purpose? Because, personally, I would prefer much more color in the image. As it is now, it seems a bit flat.</td>', 'Are the colors desaturated on purpose? Because, personally, I would prefer much more color in the image. As it is now, it seems a bit flat.', '2008-07-30 19:37:45.000000', NULL, 1),
(4851887, 704295, 93696, '<td valign="top">The fishing rods seem a little bit out of focus and blurry, and so does the sky. So I dont know what to draw my attention to.</td>', 'The fishing rods seem a little bit out of focus and blurry, and so does the sky. So I dont know what to draw my attention to.', '2008-07-30 19:40:55.000000', NULL, 1),
(4851893, 704000, 93696, '<td valign="top">Personally I would have darkened the lighting in the image, so that it seems a bit more that the light is coming from the lantern. The lantern as it is now, obviously doesnt have any purpose in the image, other than being the main object.</td>', 'Personally I would have darkened the lighting in the image, so that it seems a bit more that the light is coming from the lantern. The lantern as it is now, obviously doesnt have any purpose in the image, other than being the main object.', '2008-07-30 19:46:35.000000', NULL, 1),
(4851904, 704440, 93696, '<td valign="top">I like the idea! Simple, but yet makes you think. Personally I would have removed the hair/dust which stands out from the propeller on the top left side. It drew my attention right away - which it shouldnt...</td>', 'I like the idea! Simple, but yet makes you think. Personally I would have removed the hair/dust which stands out from the propeller on the top left side. It drew my attention right away - which it shouldnt...', '2008-07-30 19:53:06.000000', NULL, 1),
