(4905410, 703451, 94265, '<td valign="top">They taste like pears. Very nice shot!</td>', 'They taste like pears. Very nice shot!', '2008-08-23 00:20:27.000000', NULL, 0),
(4905724, 703488, 30982, '<td valign="top">A good choice for the challenge and one that works very well in B&amp;W.</td>', 'A good choice for the challenge and one that works very well in B&W.', '2008-08-23 05:13:04.000000', NULL, 0),
(4905926, 703930, 30982, '<td valign="top">The lighting is magnificent - elegance and simplicity raised a notch because of it.</td>', 'The lighting is magnificent - elegance and simplicity raised a notch because of it.', '2008-08-23 10:20:28.000000', NULL, 0),
(4906036, 703881, 76335, '<td valign="top">Brilliantly conceived and beautifully lit. I like the haphazard composition here, as if the flower were dropped into place -- the folded over single petal really makes the shot for me. Nice work!</td>', 'Brilliantly conceived and beautifully lit. I like the haphazard composition here, as if the flower were dropped into place -- the folded over single petal really makes the shot for me. Nice work!', '2008-08-23 11:15:59.000000', NULL, 0),
(4906291, 704456, 76335, '<td valign="top">Beautifully composed, brilliantly framed. Great contrast and DOF.</td>', 'Beautifully composed, brilliantly framed. Great contrast and DOF.', '2008-08-23 14:23:09.000000', NULL, 0),
(4907670, 703797, 49804, '<td valign="top">neat shot, nice composition, the lighting looks a little bit harsh, I''m not sure if you bounced the flash, if not try bouncing it off a wall, to give it softer lighting, cool shot though, nicely done.</td>', 'neat shot, nice composition, the lighting looks a little bit harsh, I''m not sure if you bounced the flash, if not try bouncing it off a wall, to give it softer lighting, cool shot though, nicely done.', '2008-08-24 13:13:18.000000', NULL, 0),
(4907723, 703009, 49804, '<td valign="top">The lighting is pretty harsh here and there isn''t really a distinct area that my eye goes straight to. Still a nice shot though.</td>', 'The lighting is pretty harsh here and there isn''t really a distinct area that my eye goes straight to. Still a nice shot though.', '2008-08-24 13:45:23.000000', NULL, 0),
